import{_ as e,o as r,c as d,a2 as a}from"./chunks/framework.z3u3TMv0.js";const g=JSON.parse('{"title":"무료 클라우드","description":"MiniTavern 무료 클라우드 API — 각사 무료/체험 한도와 영구 무료 모델, BYOK 연결. 유료 Key 없이 시작하는 방법.","frontmatter":{"title":"무료 클라우드","description":"MiniTavern 무료 클라우드 API — 각사 무료/체험 한도와 영구 무료 모델, BYOK 연결. 유료 Key 없이 시작하는 방법.","head":[["meta",{"name":"keywords","content":"주점,AI 주점,MiniTavern,AI 파트너,AI 친구,AI 로컬 채팅,Silly Tavern,SillyTavern,모바일 Silly Tavern,Silly Tavern 모바일,Silly Tavern 안드로이드,Silly Tavern iOS,AI 롤플레이,캐릭터 카드,AI 채팅,모바일 AI,오프라인 AI,AI 스토리,로컬 LLM,Ollama,LM Studio,세계관,정규식,BYOK,사용자 가이드,매뉴얼"}],["meta",{"property":"og:title","content":"무료 클라우드 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern 무료 클라우드 API — 각사 무료/체험 한도와 영구 무료 모델, BYOK 연결. 유료 Key 없이 시작하는 방법."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ko/free-cloud"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ko/free-cloud"}]]},"headers":[],"relativePath":"ko/free-cloud/index.md","filePath":"ko/free-cloud/index.md","lastUpdated":1787224147000}'),o={name:"ko/free-cloud/index.md"};function n(i,t,l,s,h,c){return r(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="무료-클라우드" tabindex="-1">무료 클라우드 <a class="header-anchor" href="#무료-클라우드" aria-label="Permalink to &quot;무료 클라우드&quot;">​</a></h1><p>MiniTavern은 <strong>BYOK(직접 키 사용)</strong> 입니다. 앱이 클라우드 한도를 주지 않으며, 각 벤더·추론 플랫폼 API Key를 직접 등록합니다.<br> 여기에서는 흔한 <strong>무료/체험 한도</strong>와 App 입력 방법을 정리합니다. 한도와 정책은 바뀌므로 <strong>각 공식 콘솔의 실시간 표시를 기준</strong>으로 하세요.</p><blockquote><p>보안: API Key는 비밀번호와 같습니다. App 기기 내 저장에만 넣고, 채팅·스크린샷·공개 저장소에 올리지 마세요.</p></blockquote><h2 id="먼저-가장-빠른-경로-고르기" tabindex="-1">먼저 가장 빠른 경로 고르기 <a class="header-anchor" href="#먼저-가장-빠른-경로-고르기" aria-label="Permalink to &quot;먼저 가장 빠른 경로 고르기&quot;">​</a></h2><table tabindex="0"><thead><tr><th>상황</th><th>추천</th><th>App 플랫폼</th></tr></thead><tbody><tr><td>중국 본토에서 빨리 채팅</td><td><a href="#zhipu-ai-glm">Zhipu Flash 무료</a> 또는 <a href="#siliconflow">SiliconFlow 무료</a></td><td>Custom (OpenAI)</td></tr><tr><td>Key 하나로 텍스트+이미지</td><td><a href="/ultra_guides/ko/free-cloud/agnes-ai">Agnes AI</a></td><td>Custom (OpenAI) / Images</td></tr><tr><td>Key 하나로 GPT/Gemini <code>*-free</code>+이미지</td><td><a href="/ultra_guides/ko/free-cloud/aihubmix">AIHubMix</a></td><td>Custom (OpenAI) / Images</td></tr><tr><td>코딩 게이트웨이, 기간제 Free 텍스트</td><td><a href="/ultra_guides/ko/free-cloud/opencode-zen">OpenCode Zen</a></td><td>Custom (OpenAI)</td></tr><tr><td>공식 중국어 LLM 체험</td><td><a href="#통의천문--알리바바-클라우드-백련">통의천문 · 알리바바 백련</a></td><td>Qwen</td></tr><tr><td>추론/코드 지향</td><td><a href="#deepseek">DeepSeek</a></td><td>DeepSeek</td></tr><tr><td>해외 계정, 멀티모달 텍스트</td><td><a href="#google-gemini">Google Gemini</a></td><td>Gemini(Google)</td></tr><tr><td>Key 하나로 다수 무료 OSS 모델</td><td><a href="/ultra_guides/ko/free-cloud/openrouter">OpenRouter <code>:free</code></a></td><td>OpenRouter</td></tr><tr><td>다른 무료 벤더 찾기</td><td><a href="/ultra_guides/ko/free-cloud/freellm">FreeLLM 목록</a>（<a href="https://github.com/open-free-llm-api/awesome-freellm-apis" target="_blank" rel="noreferrer">awesome-freellm-apis</a>）</td><td>목록 참고</td></tr><tr><td>초저지연 OSS 추론</td><td><a href="#groq">Groq</a></td><td>Custom (OpenAI)</td></tr><tr><td>클라우드 사용 안 함</td><td><a href="/ultra_guides/ko/local/">로컬 모델</a></td><td>Custom (OpenAI)</td></tr></tbody></table><p>Key 일반 절차: <a href="/ultra_guides/ko/manual/model-link">모델 연결</a>. 로컬: <a href="/ultra_guides/ko/local/">로컬 모델</a> · <a href="/ultra_guides/ko/quickstart">30분 퀵스타트</a>.</p><h2 id="minitavern에서-입력하기" tabindex="-1">MiniTavern에서 입력하기 <a class="header-anchor" href="#minitavern에서-입력하기" aria-label="Permalink to &quot;MiniTavern에서 입력하기&quot;">​</a></h2><p>경로: <strong>설정 → 모델 → 모델 연결 → 새로 만들기</strong></p><ol><li><strong>모델 플랫폼</strong>을 맞게 선택（아래 「App 플랫폼」 열）.</li><li><strong>API Key</strong> 붙여넣기. Custom이면 <strong>Base URL</strong>도.</li><li><strong>모델 ID</strong> 선택/직접 입력（벤더 문서와 완전 일치, 대소문자 구분）.</li><li><strong>테스트</strong> → 성공 후 <strong>기본값</strong>으로 설정.</li></ol><table tabindex="0"><thead><tr><th>벤더</th><th>App 플랫폼</th><th>Base URL（일반）</th><th>설명</th></tr></thead><tbody><tr><td>Gemini</td><td>Gemini(Google)</td><td>프리셋으로 충분</td><td>Gemini 프로토콜. OpenAI로 넣지 말 것</td></tr><tr><td>OpenRouter</td><td>OpenRouter</td><td>프리셋으로 충분</td><td>무료 ID는 종종 <code>:free</code></td></tr><tr><td>통의/백련</td><td>Qwen</td><td>프리셋（국제 사이트 전환 가능）</td><td><strong>일반</strong> API Key. Coding Plan 전용 Key 금지</td></tr><tr><td>DeepSeek</td><td>DeepSeek</td><td>프리셋으로 충분</td><td></td></tr><tr><td>Zhipu / SiliconFlow / Agnes / AIHubMix / Zen / Groq / Mistral 등</td><td><strong>Custom (OpenAI)</strong></td><td>각 절 참고</td><td>OpenAI 호환 게이트웨이</td></tr></tbody></table><hr><h2 id="중국-본토에서-자주-씀-직결-우선" tabindex="-1">중국 본토에서 자주 씀（직결 우선） <a class="header-anchor" href="#중국-본토에서-자주-씀-직결-우선" aria-label="Permalink to &quot;중국 본토에서 자주 씀（직결 우선）&quot;">​</a></h2><h3 id="zhipu-ai-glm" tabindex="-1">Zhipu AI (GLM) <a class="header-anchor" href="#zhipu-ai-glm" aria-label="Permalink to &quot;Zhipu AI (GLM)&quot;">​</a></h3><p>적합한 경우: <strong>장기 무료</strong>로 대화 통하기（Flash 계열）, 중국어 롤플레이에 유리.</p><table tabindex="0"><thead><tr><th>항목</th><th>내용</th></tr></thead><tbody><tr><td>공식/Key</td><td><a href="https://open.bigmodel.cn" target="_blank" rel="noreferrer">open.bigmodel.cn</a> → 콘솔 → API Keys</td></tr><tr><td>무료</td><td><code>GLM-*-Flash</code> 등 영구 무료; 신규는 체험 한도 있는 경우 많음（콘솔 확인）</td></tr><tr><td>카드 연동</td><td>보통 불필요</td></tr><tr><td>Base URL</td><td><code>https://open.bigmodel.cn/api/paas/v4</code></td></tr><tr><td>모델 예</td><td><code>glm-4.5-flash</code>, <code>glm-4.7-flash</code>（모델 광장 명칭 기준）</td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong></td></tr></tbody></table><p>절차: 가입 → API Key → Custom (OpenAI) → Base URL·Key → Flash ID → 연결 테스트.</p><h3 id="siliconflow-硅基流動" tabindex="-1">SiliconFlow（硅基流動） <a class="header-anchor" href="#siliconflow-硅基流動" aria-label="Permalink to &quot;SiliconFlow（硅基流動）&quot;">​</a></h3><p>적합한 경우: Key 하나로 여러 OSS 채팅; 일부 이미지 무료 모델.</p><table tabindex="0"><thead><tr><th>항목</th><th>내용</th></tr></thead><tbody><tr><td>공식/Key</td><td><a href="https://cloud.siliconflow.cn" target="_blank" rel="noreferrer">cloud.siliconflow.cn</a> → 계정 → API 키</td></tr><tr><td>무료</td><td><strong>무료 모델</strong>은 과금 없음（이름에 <code>Pro/</code> 없음）; 실명 후 전체 무료 모델</td></tr><tr><td>제한</td><td>모델별 고정 RPM/TPM; <a href="https://docs.siliconflow.cn/cn/userguide/rate-limits/rate-limit-and-upgradation" target="_blank" rel="noreferrer">Rate Limits</a></td></tr><tr><td>Base URL</td><td><code>https://api.siliconflow.cn/v1</code></td></tr><tr><td>모델 예</td><td>광장 「免费」 태그, 예 <code>Qwen/Qwen3-8B</code>（목록 변동）</td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong></td></tr></tbody></table><p>주의: 동명이 무료와 <code>Pro/...</code> 유료가 공존. 잘못 넣으면 과금. 청구서에서 무료 모델 소모는 0이어야 함.</p><h3 id="통의천문-·-알리바바-클라우드-백련" tabindex="-1">통의천문 · 알리바바 클라우드 백련 <a class="header-anchor" href="#통의천문-·-알리바바-클라우드-백련" aria-label="Permalink to &quot;통의천문 · 알리바바 클라우드 백련&quot;">​</a></h3><p>적합한 경우: 공식 Qwen 계열; MiniTavern에 <strong>Qwen</strong> 프리셋 있음.</p><table tabindex="0"><thead><tr><th>항목</th><th>내용</th></tr></thead><tbody><tr><td>개통</td><td><a href="https://bailian.console.aliyun.com/" target="_blank" rel="noreferrer">백련 콘솔</a>（화북 2/베이징）약관 동의 후 자동 개통</td></tr><tr><td>무료</td><td><strong>신규 무료 한도</strong>: 대부분 모델 약 <strong>100만 Token/모델</strong>, 약 <strong>90일</strong>; 모델 간 공유 불가</td></tr><tr><td>Key</td><td>백련 → API-Key; <strong>일반 Key</strong>（Token/Coding Plan 전용은 무료 한도를 <strong>소모하지 않음</strong>）</td></tr><tr><td>App</td><td><strong>Qwen</strong>（국내 프리셋; 국제 사이트 전환 가능）</td></tr><tr><td>과금 방지</td><td>콘솔에서 「<strong>무료 한도 소진 시 중지</strong>」 켜기</td></tr></tbody></table><p>공식: <a href="https://help.aliyun.com/zh/model-studio/new-free-quota" target="_blank" rel="noreferrer">신규 무료 한도</a>. 한도 종료·만료 후 호출은 과금.</p><p>이미지（만상/Qwen-Image 등）가 신규 한도 대상이면 <strong>설정 → 이미지 생성 → 이미지 연결 → Qwen</strong>. 무료 여부는 콘솔 한도 표시 확인.</p><h3 id="deepseek" tabindex="-1">DeepSeek <a class="header-anchor" href="#deepseek" aria-label="Permalink to &quot;DeepSeek&quot;">​</a></h3><p>적합한 경우: 추론·장문·가성비. 한도 후엔 저렴하지만 <strong>영구 0원이 아님</strong>.</p><table tabindex="0"><thead><tr><th>항목</th><th>내용</th></tr></thead><tbody><tr><td>공식/Key</td><td><a href="https://platform.deepseek.com" target="_blank" rel="noreferrer">platform.deepseek.com</a> → API Keys</td></tr><tr><td>무료</td><td>신규에 <strong>가입 보너스/체험</strong>이 있는 경우가 많음（금액은 콘솔）</td></tr><tr><td>App</td><td><strong>DeepSeek</strong></td></tr><tr><td>모델 예</td><td><code>deepseek-v4-flash</code>, <code>deepseek-v4-pro</code>（<a href="https://api-docs.deepseek.com/zh-cn/" target="_blank" rel="noreferrer">공식</a>）</td></tr></tbody></table><p>보너스 후 종량. 잔액 없으면 실패.</p><h3 id="modelscope-api-inference" tabindex="-1">ModelScope API-Inference <a class="header-anchor" href="#modelscope-api-inference" aria-label="Permalink to &quot;ModelScope API-Inference&quot;">​</a></h3><p>적합한 경우: 알리바바 실명 완료, 커뮤니티 OSS 추론 체험.</p><table tabindex="0"><thead><tr><th>항목</th><th>내용</th></tr></thead><tbody><tr><td>Token</td><td><a href="https://modelscope.cn" target="_blank" rel="noreferrer">modelscope.cn</a> → 액세스 토큰</td></tr><tr><td>무료</td><td>가입자 일일 요청 쿼터（<a href="https://modelscope.cn/docs/model-service/API-Inference/limits" target="_blank" rel="noreferrer">공식 한도</a>）</td></tr><tr><td>Base URL</td><td><code>https://api-inference.modelscope.cn/v1</code></td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong></td></tr></tbody></table><hr><h2 id="국제-집약-플랫폼" tabindex="-1">국제/집약 플랫폼 <a class="header-anchor" href="#국제-집약-플랫폼" aria-label="Permalink to &quot;국제/집약 플랫폼&quot;">​</a></h2><h3 id="agnes-ai" tabindex="-1">Agnes AI <a class="header-anchor" href="#agnes-ai" aria-label="Permalink to &quot;Agnes AI&quot;">​</a></h3><p>무료 Key 하나로 <strong>텍스트와 이미지</strong>（Flash 무료 대역）. 영상은 공식 사이트; App에 영상 입구 없음.</p><p>상세: <strong><a href="/ultra_guides/ko/free-cloud/agnes-ai">Agnes AI</a></strong>.</p><table tabindex="0"><thead><tr><th>항목</th><th>내용</th></tr></thead><tbody><tr><td>공식/Key</td><td><a href="https://agnes-ai.com/" target="_blank" rel="noreferrer">agnes-ai.com</a> · <a href="https://platform.agnes-ai.com/" target="_blank" rel="noreferrer">platform.agnes-ai.com</a></td></tr><tr><td>무료</td><td>Free Access: Flash 텍스트/이미지（RPM 제한）</td></tr><tr><td>Base URL</td><td><code>https://apihub.agnes-ai.com/v1</code></td></tr><tr><td>텍스트 예</td><td><code>agnes-2.5-flash</code></td></tr><tr><td>이미지 예</td><td><code>agnes-image-2.1-flash</code>（<strong>Custom (OpenAI Images)</strong>）</td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong> / <strong>Custom (OpenAI Images)</strong></td></tr></tbody></table><h3 id="opencode-zen" tabindex="-1">OpenCode Zen <a class="header-anchor" href="#opencode-zen" aria-label="Permalink to &quot;OpenCode Zen&quot;">​</a></h3><p>OpenCode 선별 게이트웨이의 <strong>Free 텍스트</strong>（예 <code>mimo-v2.5-free</code>）. 플래그십은 종량이 많음. 자동 충전 주의.</p><p>상세: <strong><a href="/ultra_guides/ko/free-cloud/opencode-zen">OpenCode Zen</a></strong>.</p><table tabindex="0"><thead><tr><th>항목</th><th>내용</th></tr></thead><tbody><tr><td>공식/Key</td><td><a href="https://opencode.ai/auth" target="_blank" rel="noreferrer">opencode.ai/auth</a> · <a href="https://opencode.ai/docs/zh-cn/zen/" target="_blank" rel="noreferrer">문서</a></td></tr><tr><td>무료</td><td>가격표 Free 모델（상한 내）</td></tr><tr><td>Base URL</td><td><code>https://opencode.ai/zen/v1</code></td></tr><tr><td>텍스트 예</td><td><code>mimo-v2.5-free</code>, <code>hy3-free</code>, <code>big-pickle</code></td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong>（chat/completions 호환 ID 우선）</td></tr></tbody></table><h3 id="aihubmix" tabindex="-1">AIHubMix <a class="header-anchor" href="#aihubmix" aria-label="Permalink to &quot;AIHubMix&quot;">​</a></h3><p>Key 하나로 보조금 <code>*-free</code>（GPT/Gemini/GLM 등）와 <strong>GPT-Image-2-free</strong>. 카드 불필요한 경우 많음.</p><p>상세: <strong><a href="/ultra_guides/ko/free-cloud/aihubmix">AIHubMix</a></strong>.</p><table tabindex="0"><thead><tr><th>항목</th><th>내용</th></tr></thead><tbody><tr><td>공식/Key</td><td><a href="https://aihubmix.com" target="_blank" rel="noreferrer">aihubmix.com</a> · <a href="https://docs.aihubmix.com/cn/blogs/free-ai-models" target="_blank" rel="noreferrer">무료 모델 글</a></td></tr><tr><td>무료</td><td>ID가 <code>-free</code>로 끝남; 모델별 RPM/일 한도</td></tr><tr><td>Base URL</td><td><code>https://aihubmix.com/v1</code></td></tr><tr><td>텍스트 예</td><td><code>gpt-4o-free</code>, <code>gpt-5.5-free</code>, <code>coding-glm-5.1-free</code></td></tr><tr><td>이미지 예</td><td><code>gpt-image-2-free</code>（<strong>Custom (OpenAI Images)</strong>）</td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong> / <strong>Custom (OpenAI Images)</strong></td></tr></tbody></table><h3 id="google-gemini" tabindex="-1">Google Gemini <a class="header-anchor" href="#google-gemini" aria-label="Permalink to &quot;Google Gemini&quot;">​</a></h3><p>멀티모달 텍스트·긴 컨텍스트. <strong>텍스트</strong> 무료 티어가 비교적 넉넉.</p><table tabindex="0"><thead><tr><th>항목</th><th>내용</th></tr></thead><tbody><tr><td>Key</td><td><a href="https://aistudio.google.com/app/apikey" target="_blank" rel="noreferrer">aistudio.google.com/app/apikey</a></td></tr><tr><td>무료</td><td>일부 Gemini Flash/Lite <strong>텍스트</strong> Free tier（RPM/RPD는 AI Studio）</td></tr><tr><td>카드</td><td>텍스트 무료는 보통 불필요; <strong>최신 이미지 API 다수는 Free 없음</strong></td></tr><tr><td>지역</td><td>EU/영국/스위스 등은 무료 불가일 수 있음</td></tr><tr><td>프라이버시</td><td>무료 프롬프트가 제품 개선에 쓰일 수 있음</td></tr><tr><td>App</td><td><strong>Gemini(Google)</strong></td></tr></tbody></table><p>채팅은 텍스트 모델（예 <code>gemini-flash-latest</code>）. <code>tts</code>/<code>image</code> 전용 ID 금지 — 테스트는 TEXT를 요구하고 TTS는 AUDIO만 → <code>response modalities (TEXT) is not supported</code>.</p><p><code>HTTP 404</code>+<code>no longer available to new users</code>: ID 폐기/신규 비공개（예 <code>gemini-2.5-flash-lite</code>）. 목록 갱신 후 온라인 Flash/Lite（예 <code>gemini-flash-latest</code>）선택.</p><p><code>HTTP 429</code>+<code>generate_content_free_tier_requests</code>（자주 limit: 20）: 무료 분당 한도. <code>Please retry in …</code> 대기. <a href="https://ai.dev/rate-limit" target="_blank" rel="noreferrer">ai.dev/rate-limit</a>.</p><p>이미지: Gemini <strong>App</strong>과 <strong>Developer API</strong> 한도가 다름. API 이미지는 Free 불가 표기가 많음. 채팅=Gemini, 이미지=집 A1111/ComfyUI 조합이 흔함 — <a href="/ultra_guides/ko/local/image-gen/">이미지 모델 배포</a>.</p><h3 id="openrouter" tabindex="-1">OpenRouter <a class="header-anchor" href="#openrouter" aria-label="Permalink to &quot;OpenRouter&quot;">​</a></h3><p>Key 하나로 많은 <strong>OSS/제3자 무료 풀</strong>. ID는 종종 <code>:free</code>. 상세: <strong><a href="/ultra_guides/ko/free-cloud/openrouter">OpenRouter</a></strong>.</p><table tabindex="0"><thead><tr><th>항목</th><th>내용</th></tr></thead><tbody><tr><td>Key</td><td><a href="https://openrouter.ai/keys" target="_blank" rel="noreferrer">openrouter.ai/keys</a></td></tr><tr><td>무료</td><td><code>:free</code>/컬렉션 Free; 약 20 RPM, 일 요청 제한; 충전 시 일 한도 상향 가능</td></tr><tr><td>App</td><td><strong>OpenRouter</strong></td></tr><tr><td>모델 예</td><td><code>openrouter/free</code>, <code>meta-llama/llama-3.3-70b-instruct:free</code>, <code>openai/gpt-oss-20b:free</code></td></tr><tr><td>컬렉션</td><td><a href="https://openrouter.ai/collections/free-models" target="_blank" rel="noreferrer">Free Models</a> · <a href="https://openairouter.net/free-models" target="_blank" rel="noreferrer">openairouter.net/free-models</a></td></tr></tbody></table><p>주의: 무료 업스트림이 프롬프트를 학습에 쓸 수 있음. <code>HTTP 429: Provider returned error</code> → 다른 <code>:free</code>, 재시도, 또는 <a href="https://openrouter.ai/settings/integrations" target="_blank" rel="noreferrer">BYOK</a>.</p><h3 id="groq" tabindex="-1">Groq <a class="header-anchor" href="#groq" aria-label="Permalink to &quot;Groq&quot;">​</a></h3><p><strong>초저지연</strong> OSS 추론용.</p><table tabindex="0"><thead><tr><th>항목</th><th>내용</th></tr></thead><tbody><tr><td>Key</td><td><a href="https://console.groq.com/keys" target="_blank" rel="noreferrer">console.groq.com/keys</a></td></tr><tr><td>무료</td><td>영구 Free tier（모델별 RPM/RPD/TPM, 변동）</td></tr><tr><td>카드</td><td>보통 불필요</td></tr><tr><td>Base URL</td><td><code>https://api.groq.com/openai/v1</code></td></tr><tr><td>모델 예</td><td><code>llama-3.1-8b-instant</code>, <code>llama-3.3-70b-versatile</code>, <code>openai/gpt-oss-20b</code></td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong></td></tr></tbody></table><h3 id="mistral-ai" tabindex="-1">Mistral AI <a class="header-anchor" href="#mistral-ai" aria-label="Permalink to &quot;Mistral AI&quot;">​</a></h3><table tabindex="0"><thead><tr><th>항목</th><th>내용</th></tr></thead><tbody><tr><td>Key</td><td><a href="https://console.mistral.ai/api-keys" target="_blank" rel="noreferrer">console.mistral.ai/api-keys</a></td></tr><tr><td>무료</td><td>Experiment/체험（월 Token은 콘솔）; 프롬프트 개선 이용 가능</td></tr><tr><td>Base URL</td><td><code>https://api.mistral.ai/v1</code></td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong></td></tr></tbody></table><h3 id="cerebras-sambanova-등-고속-추론" tabindex="-1">Cerebras / SambaNova 등 고속 추론 <a class="header-anchor" href="#cerebras-sambanova-등-고속-추론" aria-label="Permalink to &quot;Cerebras / SambaNova 등 고속 추론&quot;">​</a></h3><table tabindex="0"><thead><tr><th>플랫폼</th><th>Key</th><th>Base URL</th><th>비고</th></tr></thead><tbody><tr><td>Cerebras</td><td><a href="https://cloud.cerebras.ai/" target="_blank" rel="noreferrer">cloud.cerebras.ai</a></td><td><code>https://api.cerebras.ai/v1</code></td><td>무료는 일 Token 상한 흔함; 결제 수단 요구 가능</td></tr><tr><td>SambaNova</td><td><a href="https://cloud.sambanova.ai/apis" target="_blank" rel="noreferrer">cloud.sambanova.ai</a></td><td><code>https://api.sambanova.ai/v1</code></td><td>영구 무료+일시 보너스; 제한 엄격</td></tr></tbody></table><p>App 모두 <strong>Custom (OpenAI)</strong>. 모델명은 각 콘솔 기준.</p><h3 id="github-models" tabindex="-1">GitHub Models <a class="header-anchor" href="#github-models" aria-label="Permalink to &quot;GitHub Models&quot;">​</a></h3><table tabindex="0"><thead><tr><th>항목</th><th>내용</th></tr></thead><tbody><tr><td>입구</td><td><a href="https://github.com/marketplace/models" target="_blank" rel="noreferrer">GitHub Models</a></td></tr><tr><td>인증</td><td>GitHub Personal Access Token</td></tr><tr><td>Base URL</td><td><code>https://models.github.ai/inference</code></td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong></td></tr><tr><td>제한</td><td>모델별 RPM/RPD — 가벼운 체험용</td></tr></tbody></table><h3 id="nvidia-nim" tabindex="-1">NVIDIA NIM <a class="header-anchor" href="#nvidia-nim" aria-label="Permalink to &quot;NVIDIA NIM&quot;">​</a></h3><table tabindex="0"><thead><tr><th>항목</th><th>내용</th></tr></thead><tbody><tr><td>입구</td><td><a href="https://build.nvidia.com/explore/discover" target="_blank" rel="noreferrer">build.nvidia.com</a></td></tr><tr><td>Base URL</td><td><code>https://integrate.api.nvidia.com/v1</code></td></tr><tr><td>App</td><td><strong>Custom (OpenAI)</strong>（이후 Nvidia 프리셋 복구 시 선택 가능）</td></tr></tbody></table><hr><h2 id="체험-한도-영구-무료-아님" tabindex="-1">체험 한도（영구 무료 아님） <a class="header-anchor" href="#체험-한도-영구-무료-아님" aria-label="Permalink to &quot;체험 한도（영구 무료 아님）&quot;">​</a></h2><p>평가용. 장기 유일한 백엔드로는 부적합:</p><table tabindex="0"><thead><tr><th>벤더</th><th>흔한 상황</th><th>App</th></tr></thead><tbody><tr><td>OpenAI</td><td>콘솔 일시 크레딧; 본가 API에 <strong>안정적 영구 무료 없음</strong></td><td>ChatGPT(OpenAI)</td></tr><tr><td>Anthropic Claude</td><td>starter credits, 빨리 소진</td><td>Claude(Anthropic)</td></tr><tr><td>DeepSeek</td><td>위 가입 보너스</td><td>DeepSeek</td></tr><tr><td>알리바바 백련</td><td>신규 Token 한도（약 90일）</td><td>Qwen</td></tr></tbody></table><p>소진 후: Key 삭제, 「무료 소진 시 중지」, 무료 모델/로컬로 전환.</p><hr><h2 id="무료-이미지-생성" tabindex="-1">무료 이미지 생성 <a class="header-anchor" href="#무료-이미지-생성" aria-label="Permalink to &quot;무료 이미지 생성&quot;">​</a></h2><table tabindex="0"><thead><tr><th>경로</th><th>비용</th><th>설명</th></tr></thead><tbody><tr><td><a href="/ultra_guides/ko/local/image-gen/">집 A1111 / ComfyUI</a></td><td>전기+GPU</td><td>장수 제한 없음; 폰→PC LAN</td></tr><tr><td>SiliconFlow 무료 이미지 모델</td><td>무료 모델 0원</td><td>이미지 연결 <strong>Custom (OpenAI Images)</strong>, Base URL은 硅基 <code>…/v1</code></td></tr><tr><td><a href="/ultra_guides/ko/free-cloud/agnes-ai">Agnes AI</a> Image Flash</td><td>Free Access</td><td><strong>Custom (OpenAI Images)</strong>, <code>https://apihub.agnes-ai.com/v1</code>, 예 <code>agnes-image-2.1-flash</code></td></tr><tr><td><a href="/ultra_guides/ko/free-cloud/aihubmix">AIHubMix</a></td><td><code>*-free</code> 이미지</td><td><strong>Custom (OpenAI Images)</strong>, <code>https://aihubmix.com/v1</code>, 예 <code>gpt-image-2-free</code></td></tr><tr><td>통의 만상 / Qwen 이미지</td><td>백련 해당 한도 확인</td><td><strong>설정 → 이미지 생성 → 이미지 연결 → Qwen</strong></td></tr><tr><td>OpenAI / 다수 Gemini 이미지 API</td><td>보통 유료</td><td>안정 Free 없으면 「무료 이미지」로 쓰지 말 것</td></tr></tbody></table><p>채팅과 이미지 연결은 분리 가능: 예 채팅=Zhipu Flash, 이미지=집 ComfyUI.</p><hr><h2 id="사용-팁과-문제-해결" tabindex="-1">사용 팁과 문제 해결 <a class="header-anchor" href="#사용-팁과-문제-해결" aria-label="Permalink to &quot;사용 팁과 문제 해결&quot;">​</a></h2><ol><li><strong>먼저 연결 테스트</strong>: 실패 시 「상세」→ <a href="/ultra_guides/ko/manual/errors">오류 코드</a>.</li><li><strong>429 / 속도 제한</strong>: 가벼운 모델, 기억 단축, 다른 무료 백엔드.</li><li><strong>갑작스러운 과금</strong>: <code>Pro/</code> 모델? 백련 중지 미설정? 보너스 소진?</li><li><strong>프라이버시</strong>: 무료 티어는 로그 학습이 흔함 — 민감 내용은 <a href="/ultra_guides/ko/local/">로컬</a>.</li><li><strong>한도 변경</strong>: 수치는 조사 시점 참고. 색인: <a href="/ultra_guides/ko/free-cloud/freellm">FreeLLM</a>（<a href="https://github.com/open-free-llm-api/awesome-freellm-apis" target="_blank" rel="noreferrer">awesome-freellm-apis</a> · <a href="https://freellm.net" target="_blank" rel="noreferrer">freellm.net</a>）.</li></ol><h2 id="관련-장" tabindex="-1">관련 장 <a class="header-anchor" href="#관련-장" aria-label="Permalink to &quot;관련 장&quot;">​</a></h2><ul><li><a href="/ultra_guides/ko/manual/model-link">모델 연결</a> — App 입력</li><li><a href="/ultra_guides/ko/manual/getting-started">처음 사용</a></li><li><a href="/ultra_guides/ko/free-cloud/freellm">FreeLLM 목록</a></li><li><a href="/ultra_guides/ko/local/">로컬 모델</a></li><li><a href="/ultra_guides/ko/local/image-gen/">이미지 모델 배포</a> — A1111 / ComfyUI</li></ul>',83)])])}const u=e(o,[["render",n]]);export{g as __pageData,u as default};
